import React, { useState } from "react";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import api from "../api";
import { useNavigate, useParams } from "react-router-dom";
import Container from "react-bootstrap/esm/Container";

const NewBook = () => {
  const { origin_id } = useParams();
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [image, setImage] = useState(null);
  const [branchInfo, setBranchInfo] = useState("");
  const navigate = useNavigate();

  const handleCreateBook = async () => {
    const formData = new FormData();
    formData.append("title", title);
    formData.append("content", content);
    formData.append("origin_book_id", origin_id)
    formData.append("branch_info", branchInfo)
    if (image) {
      formData.append("image", image); // Attach the image file if selected
    }

    try {
      await api.post("/api/create-book", formData, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
          "Content-Type": "multipart/form-data",
        },
      });
      setTitle("");
      setContent("");
      setImage(null);
      navigate('/my-books');
      //alert("Book created succesfully");
    } catch (err) {
      console.error("Error creating book:", err);
    }
  };

  return (
    <Container className="justify-content-center box">
      <span className="justify-content-center">
        <h3>Create New Book</h3>
      </span>
      <Form onSubmit={handleCreateBook}>
        <Form.Group className="mb-3">
          <Form.Label>Book Title</Form.Label>
          <Form.Control
            id="title"
            placeholder="Epic title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Book Description</Form.Label>
          <Form.Control
            as="textarea"
            rows={3}
            id="desc"
            placeholder="Epic description"
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
        </Form.Group>
        <Form.Group controlId="formFile" className="mb-3">
          <Form.Label>Upload Cover Photo</Form.Label>
          <Form.Control
            type="file"
            onChange={(e) => setImage(e.target.files[0])}
            accept="image/*"
          />
        </Form.Group>
        <Button variant="primary" type="submit">
          Submit
        </Button>
      </Form>
    </Container>
  );
};

export default NewBook;
